list_tax_profiles.code:
import (
	"fmt"
)

resp, err := client.TaxProfiles().ListTaxProfiles(ctx, map[string]any{"limit": 20}, nil)
if err != nil {
	log.Fatal(err)
}
for _, row := range resp.Map().(map[string]any)["tax_profiles"].([]any) {
	profile := row.(map[string]any)
	fmt.Println(profile["id"], profile["name"], profile["default"])
}

